//! Minimal Floom app for OpenHarmony (HarmonyOS).
//!
//! Unlike Android (`android_main`) or iOS (`UIApplicationMain` reached through
//! winit), OpenHarmony starts the UI from ArkTS (`EntryAbility` / XComponent).
//! The Rust side therefore exposes two FFI surfaces:
//!
//! 1. A **C-ABI runtime entry** generated by
//!    [`floom_winit_ohos::export_ohos_winit_app!`] — the `ohos_winit_runtime_*`
//!    symbols the ArkTS/NAPI layer calls to drive the winit event loop.
//! 2. **N-API bridges** (`register_platform_bridge`, `on_file_picked`,
//!    `on_shared_files`, `on_accessibility_action`) that ArkTS calls *back*
//!    into (see `entry/src/main/ets/FloomBridge.ets`).
//!
//! The runtime entry only needs a *factory*: a function that builds a
//! [`floom::Application`] with at least one window. The OHOS runtime drains
//! `initial_windows` inside `can_create_surfaces`.
//!
//! ```bash
//! # Build & package with cargo-ohos-app (see README.md), then run on a
//! # device or the OHOS emulator.
//! cargo ohos --target aarch64-unknown-linux-ohos
//! ```

#[cfg(target_env = "ohos")]
floom_winit_ohos::export_ohos_winit_app!(ohos_factory);

/// Bridge the `log` crate (wgpu / floom internals) to hilog: stderr is a no-op
/// on OHOS, so GPU errors would otherwise be invisible.
#[cfg(target_env = "ohos")]
struct HilogLogger;

#[cfg(target_env = "ohos")]
static HILOG_LOGGER: HilogLogger = HilogLogger;

#[cfg(target_env = "ohos")]
impl log::Log for HilogLogger {
    fn enabled(&self, metadata: &log::Metadata) -> bool {
        metadata.level() <= log::Level::Info
    }

    fn log(&self, record: &log::Record) {
        if self.enabled(record.metadata()) {
            let level = match record.level() {
                log::Level::Error => floom_winit_ohos::OhosLogLevel::Error,
                log::Level::Warn => floom_winit_ohos::OhosLogLevel::Warn,
                log::Level::Info => floom_winit_ohos::OhosLogLevel::Info,
                _ => floom_winit_ohos::OhosLogLevel::Debug,
            };
            floom_winit_ohos::deveco_log_with_level(
                level,
                format!("{}: {}", record.target(), record.args()),
            );
        }
    }

    fn flush(&self) {}
}

#[cfg(target_env = "ohos")]
fn ohos_factory() -> floom::Application {
    // Surface wgpu / renderer diagnostics in hilog.
    let _ = log::set_logger(&HILOG_LOGGER);
    log::set_max_level(log::LevelFilter::Info);

    // `floom_app_factory()` in floom core returns an `Application` with *no*
    // window; apps must build their own factory that also calls `.window(...)`
    // so the OHOS runtime has something to surface.
    floom::Application::new_ohos(floom::AppConfig::default()).window(|_id| app_view(), None)
}

#[cfg(target_env = "ohos")]
fn app_view() -> impl floom::view::IntoView {
    use floom::prelude::*;
    let counter = RwSignal::new(0);
    let text = RwSignal::new(String::new());

    Stack::vertical((
        // A small counter to prove pointer input + redraw work.
        Stack::horizontal((
            Button::new("+").action(move || counter.update(|v| *v += 1)),
            Label::derived(move || format!("Value: {}", counter.get())),
            Button::new("-").action(move || counter.update(|v| *v -= 1)),
        ))
        .style(|s| s.gap(10.0)),
        // A text field — exercises the OHOS IME / soft keyboard bridge.
        TextInput::new(text),
        Label::derived(move || format!("You typed: {}", text.get())),
    ))
    .style(|s| {
        s.size_full()
            .flex_col()
            .items_center()
            .justify_center()
            .gap(12.0)
    })
}
